#include <vector>
#include <unordered_map>
#include <algorithm>

class Solution {
public:
    std::vector<int> longestSpecialPath(std::vector<std::vector<int>>& edges, std::vector<int>& nums) {
        int n = nums.size();
        std::vector<std::vector<std::pair<int, int>>> adj(n);
        for (const auto& e : edges) {
            adj[e[0]].emplace_back(e[1], e[2]);
            adj[e[1]].emplace_back(e[0], e[2]);
        }

        std::unordered_map<int, int> pos;
        std::vector<int> dist = {0};
        std::vector<int> path = {0};
        int max_len = 0;
        int min_nodes = 1;

        auto dfs = [&](auto&& self, int u, int p, int top_idx) -> void {
            int val = nums[u];
            int prev_depth = pos.count(val) ? pos[val] : -1;
            int new_top = std::max(top_idx, prev_depth + 1);

            int curr_len = dist.back() - dist[new_top];
            int curr_nodes = (int)path.size() - new_top;
            if (curr_len > max_len) {
                max_len = curr_len;
                min_nodes = curr_nodes;
            } else if (curr_len == max_len && curr_len > 0) {
                min_nodes = std::min(min_nodes, curr_nodes);
            }

            pos[val] = (int)path.size() - 1;
            for (const auto& edge : adj[u]) {
                int v = edge.first;
                int w = edge.second;
                if (v != p) {
                    dist.push_back(dist.back() + w);
                    path.push_back(v);
                    self(self, v, u, new_top);
                    path.pop_back();
                    dist.pop_back();
                }
            }
            if (prev_depth != -1) {
                pos[val] = prev_depth;
            } else {
                pos.erase(val);
            }
        };

        dfs(dfs, 0, -1, 0);
        return {max_len, min_nodes};
    }
};

import java.util.*;

class Solution {
    private int maxLen = 0;
    private int minNodes = 1;

    public int[] longestSpecialPath(int[][] edges, int[] nums) {
        int n = nums.length;
        List<int[]>[] adj = new ArrayList[n];
        for (int i = 0; i < n; i++) adj[i] = new ArrayList<>();
        for (int[] e : edges) {
            adj[e[0]].add(new int[]{e[1], e[2]});
            adj[e[1]].add(new int[]{e[0], e[2]});
        }

        Map<Integer, Integer> pos = new HashMap<>();
        List<Integer> dist = new ArrayList<>();
        dist.add(0);
        List<Integer> path = new ArrayList<>();
        path.add(0);

        dfs(0, -1, 0, adj, nums, pos, dist, path);
        return new int[]{maxLen, minNodes};
    }

    private void dfs(int u, int p, int topIdx, List<int[]>[] adj, int[] nums, Map<Integer, Integer> pos, List<Integer> dist, List<Integer> path) {
        int val = nums[u];
        int prevDepth = pos.getOrDefault(val, -1);
        int newTop = Math.max(topIdx, prevDepth + 1);

        int currLen = dist.get(dist.size() - 1) - dist.get(newTop);
        int currNodes = path.size() - newTop;
        if (currLen > maxLen) {
            maxLen = currLen;
            minNodes = currNodes;
        } else if (currLen == maxLen && currLen > 0) {
            minNodes = Math.min(minNodes, currNodes);
        }

        pos.put(val, path.size() - 1);
        for (int[] edge : adj[u]) {
            int v = edge[0];
            int w = edge[1];
            if (v != p) {
                dist.add(dist.get(dist.size() - 1) + w);
                path.add(v);
                dfs(v, u, newTop, adj, nums, pos, dist, path);
                path.remove(path.size() - 1);
                dist.remove(dist.size() - 1);
            }
        }
        if (prevDepth != -1) {
            pos.put(val, prevDepth);
        } else {
            pos.remove(val);
        }
    }
}

var longestSpecialPath = function(edges, nums) {
    const n = nums.length;
    const adj = Array.from({ length: n }, () => []);
    for (const [u, v, w] of edges) {
        adj[u].push([v, w]);
        adj[v].push([u, w]);
    }

    const pos = new Map();
    const dist = [0];
    const path = [0];
    let maxLen = 0;
    let minNodes = 1;

    function dfs(u, p, topIdx) {
        const val = nums[u];
        const prevDepth = pos.has(val) ? pos.get(val) : -1;
        const newTop = Math.max(topIdx, prevDepth + 1);

        const currLen = dist[dist.length - 1] - dist[newTop];
        const currNodes = path.length - newTop;
        if (currLen > maxLen) {
            maxLen = currLen;
            minNodes = currNodes;
        } else if (currLen === maxLen && currLen > 0) {
            minNodes = Math.min(minNodes, currNodes);
        }

        pos.set(val, path.length - 1);
        for (const [v, w] of adj[u]) {
            if (v !== p) {
                dist.push(dist[dist.length - 1] + w);
                path.push(v);
                dfs(v, u, newTop);
                path.pop();
                dist.pop();
            }
        }
        if (prevDepth !== -1) {
            pos.set(val, prevDepth);
        } else {
            pos.delete(val);
        }
    }

    dfs(0, -1, 0);
    return [maxLen, minNodes];
};
